'use strict';
const assert = require('assert');
const EventEmitter = require('./');

{
  const emitter = new EventEmitter();
  const context = {};
  const calls = [];
  function listener() { calls.push(this); }
  emitter.on('event', listener, context);
  emitter.once('event', listener, context);
  const unsubscribe = emitter.subscribe('event', listener, context);
  assert.deepStrictEqual(emitter.listeners('event'), [listener, listener, listener]);
  unsubscribe();
  unsubscribe();
  assert.strictEqual(emitter.listenerCount('event'), 2);
  emitter.emit('event');
  assert.deepStrictEqual(calls, [context, context]);
}

{
  const emitter = new EventEmitter();
  function listener() {}
  const unsubscribe = emitter.subscribe('event', listener);
  emitter.removeListener('event', listener);
  emitter.on('event', listener);
  unsubscribe();
  assert.deepStrictEqual(emitter.listeners('event'), [listener]);
  emitter.removeAllListeners('event');
  const second = emitter.subscribe('event', listener);
  emitter.removeAllListeners('event');
  emitter.on('event', listener);
  second();
  assert.deepStrictEqual(emitter.listeners('event'), [listener]);
}

{
  const emitter = new EventEmitter();
  const context = { value: 1 };
  let received;
  const unsubscribe = emitter.subscribe('event', function () {
    received = [this, Array.from(arguments)];
  }, context);
  emitter.emit('event', 0, 1, 2, 3, 4, 5, 6, 7, 8);
  assert.deepStrictEqual(received, [context, [0, 1, 2, 3, 4, 5, 6, 7, 8]]);
  unsubscribe();
  assert.deepStrictEqual(emitter.eventNames(), []);
}

{
  const emitter = new EventEmitter();
  const event = Symbol('event');
  const unsubscribe = emitter.subscribe(event, function () {});
  assert.deepStrictEqual(emitter.eventNames(), [event]);
  unsubscribe();
  assert.deepStrictEqual(emitter.eventNames(), []);
}

{
  const emitter = new EventEmitter();
  const listener = function () {};
  emitter.on('event', listener);
  assert.throws(() => emitter.subscribe('event', null));
  assert.deepStrictEqual(emitter.listeners('event'), [listener]);
}

{
  const emitter = new EventEmitter();
  const calls = [];
  let unsubscribeSecond;
  emitter.subscribe('event', () => {
    calls.push('first');
    unsubscribeSecond();
  });
  unsubscribeSecond = emitter.subscribe('event', () => calls.push('second'));
  emitter.emit('event');
  emitter.emit('event');
  assert.deepStrictEqual(calls, ['first', 'second', 'first']);
}

{
  const emitter = new EventEmitter();
  let calls = 0;
  let unsubscribe;
  unsubscribe = emitter.subscribe('event', () => {
    calls++;
    unsubscribe();
    emitter.emit('event');
  });
  emitter.emit('event');
  assert.strictEqual(calls, 1);
  assert.strictEqual(emitter.emit('event'), false);
}
